    for i in range (n):
        t[i]=int(input("t["+str(i)+"]= "))

def tri(n,t):
    for i in range (n-1) :
        idmin = mini(t,i,n)
        if idmin != i :
            temp = t[i]
            t[i] = t[idmin]
            t[idmin] = temp

